<?php $__env->startSection('content'); ?><div class="page-head"><div><div class="eyebrow">PAYMENT MANAGEMENT</div><h1>Payments</h1><p>Gateway-aware payment operations with status, verification and auditability.</p></div><a class="btn primary" href="<?php echo e(route('payments.create')); ?>">+ New Payment</a></div><div class="panel"><form class="toolbar"><input name="q" value="<?php echo e(request('q')); ?>" placeholder="Payment reference or gateway ID"><select name="status"><option value="">All statuses</option><?php $__currentLoopData = ['created','pending','processing','successful','failed','cancelled','refunded']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $s): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($s); ?>" <?php if(request('status')===$s): echo 'selected'; endif; ?>><?php echo e(ucfirst($s)); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><select name="gateway"><option value="">All gateways</option><option value="mock">Mock</option><option value="razorpay">Razorpay</option><option value="paytm">Paytm</option></select><button class="btn secondary">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Payment</th><th>Business</th><th>Card</th><th>Amount</th><th>Gateway</th><th>Status</th><th>Created</th></tr></thead><tbody><?php $__currentLoopData = $payments; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $p): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><tr><td><a class="link mono" href="<?php echo e(route('payments.show',$p)); ?>"><?php echo e($p->reference); ?></a></td><td><?php echo e($p->business->name); ?></td><td><?php echo e($p->card?->reference ?? '—'); ?></td><td>₹<?php echo e(number_format($p->amount,2)); ?></td><td><?php echo e(strtoupper($p->gateway)); ?></td><td><span class="badge <?php echo e($p->status->value); ?>"><?php echo e(ucfirst($p->status->value)); ?></span></td><td><?php echo e($p->created_at->format('d M Y H:i')); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></tbody></table></div><div class="pagination"><?php echo e($payments->links()); ?></div></div><?php $__env->stopSection(); ?>

